<div class="eyebrow">VOTRE ESPACE ECOAGRI</div><h1><?= e($module['name']) ?></h1><p class="intro"><?= e($module['description']) ?></p><?php if ($error): ?><p class="flash flash-error" role="alert"><?= e($error) ?></p><?php else: ?><section class="panel data-panel"><div class="table-toolbar"><div><h2>Les données de votre espace</h2><span class="muted"><?= count($rows) ?> résultat(s) · 200 maximum</span></div><label class="search-label">Rechercher<input type="search" data-table-search placeholder="Filtrer les résultats…"></label></div><?php if (!$rows): ?><div class="empty-state"><span class="module-icon"><?= e($module['icon']) ?></span><h3>Tout commence ici.</h3><p>Aucun enregistrement disponible pour le moment.<br>Les données ajoutées à votre exploitation apparaîtront dans cet espace.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><?php foreach (array_keys($rows[0]) as $column): ?><th scope="col"><?= e($column) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><?php foreach ($row as $value): ?><td><?= e($value??'—') ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><p data-no-results hidden class="empty-state">Aucun résultat pour cette recherche.</p><?php endif; ?></section><?php endif; ?><p class="muted">Consultation uniquement · Les formulaires de gestion seront ajoutés lors de l’étape CRUD.</p>
